using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- Options with a default resolver (resolves any type) ---
var webOptions = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1) GetTypeInfo<T>() — returns JsonTypeInfo<T> directly, no cast needed.
JsonTypeInfo<Person> personInfo = webOptions.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"  Serialized: {json}");

// 2) TryGetTypeInfo<T>() — probe without throwing.
if (webOptions.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
{
    Console.WriteLine($"TryGetTypeInfo<Person> → found ({info!.Type.Name})");
}

// --- Options with a source-gen resolver (only knows about WeatherForecast) ---
var sgOptions = new JsonSerializerOptions
{
    TypeInfoResolver = WeatherContext.Default
};

if (sgOptions.TryGetTypeInfo<WeatherForecast>(out JsonTypeInfo<WeatherForecast>? wInfo))
{
    Console.WriteLine($"\nTryGetTypeInfo<WeatherForecast> → found ({wInfo!.Type.Name})");
    Console.WriteLine($"  Serialized: {JsonSerializer.Serialize(new WeatherForecast("Sunny", 28), wInfo)}");
}

// Person is NOT in the source-gen context, so TryGetTypeInfo returns false.
if (!sgOptions.TryGetTypeInfo<Person>(out _))
{
    Console.WriteLine("TryGetTypeInfo<Person> on source-gen options → NOT found (no exception!)");
}

// --- Types ---------------------------------------------------------------

public record Person(string Name, int Age);

public record WeatherForecast(string Summary, int TempC);

[JsonSerializable(typeof(WeatherForecast))]
public partial class WeatherContext : JsonSerializerContext;

